"""Evaluation helpers.  Scores are always produced *before* labels are read (R10)."""

from __future__ import annotations

import numpy as np
from sklearn.metrics import average_precision_score, precision_recall_curve, roc_auc_score


def auc_roc(scores: np.ndarray, labels: np.ndarray) -> float:
    return float(roc_auc_score(labels, scores))


def auc_pr(scores: np.ndarray, labels: np.ndarray) -> float:
    """Primary AUC-PR: sklearn average_precision_score (ADBench convention)."""
    return float(average_precision_score(labels, scores))


def auc_pr_trapezoid(scores: np.ndarray, labels: np.ndarray) -> float:
    """Secondary AUC-PR: trapezoidal integral of the PR curve."""
    p, r, _ = precision_recall_curve(labels, scores)
    return float(np.trapz(p, r))


def evaluate_scores(scores: np.ndarray, labels: np.ndarray) -> dict:
    """Consume scores first, labels second - the unsupervised contract (R9, R10)."""
    return {
        "auc_roc": auc_roc(scores, labels),
        "auc_pr": auc_pr(scores, labels),
        "auc_pr_trapezoid": auc_pr_trapezoid(scores, labels),
    }


def summarize(values) -> dict:
    v = np.asarray(list(values), dtype=np.float64)
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "std_pop": float(v.std(ddof=0)),
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(v.size),
        "values": [float(x) for x in v],
    }

